rule CobaltStrike_Shellcode {
    meta:
        description = "Detects memory patterns associated with Cobalt Strike shellcode"
        author = "SOC_Team"
        last_modified = "2026-04-09"
    strings:
        $a = { FF E0 }
        $b = { 6A 00 68 [4] 64 A1 [4] 6A [4] 50 6A [4] 6A 00 68 [4] 68 [4] FF D0 }
        $c = "CryptProtectMemory" wide ascii
    condition:
        all of them
}

